const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});
const clean=s=>(s||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
const year=v=>String(v||'').match(/\d{4}/)?.[0]||null;
async function openLibrary(q){const u=new URL('https://openlibrary.org/search.json');u.searchParams.set('q',q);u.searchParams.set('limit','6');u.searchParams.set('fields','key,title,author_name,first_publish_year,cover_i,subject');const r=await fetch(u,{headers:{'user-agent':'TasteConstellation/1.0'}});if(!r.ok)throw new Error(`Open Library ${r.status}`);const d=await r.json();return(d.docs||[]).map(x=>({id:`openlibrary:${x.key}`,externalId:x.key,title:x.title,originalTitle:null,creator:x.author_name?.slice(0,2).join(', ')||'작자 미상',year:x.first_publish_year||null,mediaType:'BOOK',posterUrl:x.cover_i?`https://covers.openlibrary.org/b/id/${x.cover_i}-M.jpg`:null,description:'Open Library 도서 정보',tags:(x.subject||[]).slice(0,8),source:'Open Library'}))}
async function aniList(q){const query=`query($search:String){Page(page:1,perPage:6){media(search:$search,type:ANIME,sort:SEARCH_MATCH){id title{userPreferred native} description(asHtml:false) startDate{year} coverImage{large} genres tags{rank name} staff(perPage:1,sort:RELEVANCE){nodes{name{full}}}}}}`;const r=await fetch('https://graphql.anilist.co',{method:'POST',headers:{'content-type':'application/json','accept':'application/json'},body:JSON.stringify({query,variables:{search:q}})});if(!r.ok)throw new Error(`AniList ${r.status}`);const d=await r.json();return(d.data?.Page?.media||[]).map(x=>({id:`anilist:${x.id}`,externalId:String(x.id),title:x.title.userPreferred,originalTitle:x.title.native,creator:x.staff?.nodes?.[0]?.name?.full||'제작진 정보 없음',year:x.startDate?.year||null,mediaType:'ANIME',posterUrl:x.coverImage?.large||null,description:clean(x.description)||'AniList 애니메이션 정보',tags:[...(x.genres||[]),...(x.tags||[]).sort((a,b)=>b.rank-a.rank).slice(0,6).map(t=>t.name)].slice(0,10),source:'AniList'}))}
async function tmdb(q,env){if(!env.TMDB_READ_TOKEN)return[];const u=new URL('https://api.themoviedb.org/3/search/multi');u.searchParams.set('query',q);u.searchParams.set('language','ko-KR');u.searchParams.set('include_adult','false');const r=await fetch(u,{headers:{authorization:`Bearer ${env.TMDB_READ_TOKEN}`,accept:'application/json'}});if(!r.ok)throw new Error(`TMDB ${r.status}`);const d=await r.json();return(d.results||[]).filter(x=>x.media_type==='movie'||x.media_type==='tv').slice(0,6).map(x=>({id:`tmdb:${x.media_type}:${x.id}`,externalId:String(x.id),title:x.title||x.name,originalTitle:x.original_title||x.original_name,creator:x.media_type==='movie'?'영화':'TV 시리즈',year:year(x.release_date||x.first_air_date),mediaType:x.media_type==='movie'?'FILM':'TV',posterUrl:x.poster_path?`https://image.tmdb.org/t/p/w342${x.poster_path}`:null,description:x.overview||'TMDB 작품 정보',tags:[],source:'TMDB'}))}
async function googleBooks(q,env){if(!env.GOOGLE_BOOKS_API_KEY)return[];const u=new URL('https://www.googleapis.com/books/v1/volumes');u.searchParams.set('q',q);u.searchParams.set('maxResults','6');u.searchParams.set('key',env.GOOGLE_BOOKS_API_KEY);const r=await fetch(u);if(!r.ok)throw new Error(`Google Books ${r.status}`);const d=await r.json();return(d.items||[]).map(x=>{const v=x.volumeInfo||{};return{id:`googlebooks:${x.id}`,externalId:x.id,title:v.title,originalTitle:null,creator:(v.authors||[]).join(', ')||'작자 미상',year:year(v.publishedDate),mediaType:'BOOK',posterUrl:v.imageLinks?.thumbnail?.replace('http:','https:')||null,description:clean(v.description)||'Google Books 도서 정보',tags:(v.categories||[]).slice(0,8),source:'Google Books'}})}
function dedupe(items){const seen=new Set();return items.filter(x=>{const k=`${x.mediaType}:${x.title}`.toLowerCase().replace(/\s/g,'');if(seen.has(k))return false;seen.add(k);return true}).slice(0,18)}
async function search(request,env){const u=new URL(request.url),q=(u.searchParams.get('q')||'').trim();if(q.length<2)return json({items:[],sources:{},message:'두 글자 이상 입력해 주세요.'});const providers=[['TMDB',tmdb(q,env)],['Google Books',googleBooks(q,env)],['Open Library',openLibrary(q)],['AniList',aniList(q)]],settled=await Promise.allSettled(providers.map(x=>x[1]));let items=[];const sources={};settled.forEach((r,i)=>{const name=providers[i][0],configured=!(name==='TMDB'&&!env.TMDB_READ_TOKEN)&&!(name==='Google Books'&&!env.GOOGLE_BOOKS_API_KEY);sources[name]=!configured?'needs_key':r.status==='fulfilled'?'ok':'error';if(r.status==='fulfilled')items.push(...r.value)});return json({items:dedupe(items),sources,query:q})}
function currentUser(request){const id=request.headers.get('oai-authenticated-user-id');if(!id)return null;return{id,email:request.headers.get('oai-authenticated-user-email')||null}}
function dbReady(env){return Boolean(env.SUPABASE_URL&&env.SUPABASE_SERVICE_ROLE_KEY)}
async function supabase(env,path,{method='GET',body,prefer}={}){const r=await fetch(`${env.SUPABASE_URL}/rest/v1/${path}`,{method,headers:{apikey:env.SUPABASE_SERVICE_ROLE_KEY,authorization:`Bearer ${env.SUPABASE_SERVICE_ROLE_KEY}`,'content-type':'application/json',...(prefer?{prefer}:{})},body:body===undefined?undefined:JSON.stringify(body)});if(!r.ok)throw new Error(`Supabase ${r.status}: ${(await r.text()).slice(0,300)}`);if(r.status===204)return null;const text=await r.text();return text?JSON.parse(text):null}
async function ensureProfile(env,user){await supabase(env,'profiles?on_conflict=id',{method:'POST',prefer:'resolution=merge-duplicates,return=minimal',body:{id:user.id,display_name:user.email||'Taste Constellation user'}})}
function normalizeWork(w){return{id:String(w.id||'').slice(0,240),external_id:String(w.externalId||'').slice(0,240),title:String(w.title||'').slice(0,500),original_title:w.originalTitle?String(w.originalTitle).slice(0,500):null,creator:String(w.creator||'작자 미상').slice(0,500),release_year:w.year?Number(w.year)||null:null,media_type:String(w.mediaType||w.type||'OTHER').slice(0,32),poster_url:w.posterUrl?String(w.posterUrl).slice(0,1500):null,description:String(w.description||w.quote||'').slice(0,4000),tags:Array.isArray(w.tags)?w.tags.slice(0,16).map(x=>String(x).slice(0,100)):[],source:String(w.source||'Taste Constellation').slice(0,100)}}
function toClientWork(row,a={}){return{id:row.id,externalId:row.external_id,title:row.title,originalTitle:row.original_title,creator:row.creator,year:row.release_year,mediaType:row.media_type,posterUrl:row.poster_url,description:row.description,tags:row.tags||[],source:row.source,rating:a.rating||null,myComment:a.my_comment||'',aiComment:a.ai_comment||'',analysisStatus:a.analysis_status||'pending',analysis:a.analysis_json||null,savedAt:a.created_at||null}}
const LEXICON=[
 ['고독','MOOD',['고독','외로','lonely','loneliness','isolation','alienation','소외','홀로']],
 ['자아정체성','IDEA',['정체성','자아','identity','self','나는 누구','personhood']],
 ['기억','IDEA',['기억','memory','memories','망각','과거','회상']],
 ['상실','MOOD',['상실','loss','grief','이별','떠나','죽음','death','mourning']],
 ['성장','STORY',['성장','coming of age','youth','청춘','소년','소녀','어른']],
 ['가족','STORY',['가족','family','부모','아버지','어머니','parent','child','형제','자매']],
 ['사랑과 친밀감','MOOD',['사랑','love','romance','연인','친밀','relationship','marriage']],
 ['인간과 비인간','IDEA',['인공지능','android','robot','cyborg','ai ','인간성','non-human','비인간','artificial']],
 ['계급과 불평등','IDEA',['계급','class','poverty','가난','부자','inequality','불평등','노동','capital']],
 ['권력과 통제','IDEA',['권력','power','control','통제','독재','정부','조직','감시','surveillance']],
 ['존재와 죽음','IDEA',['존재','existence','죽음','death','삶의 의미','mortality','영혼']],
 ['연결의 실패','MOOD',['소통','연결','communication','disconnect','오해','관계','고립']],
 ['종말과 재난','STORY',['종말','apocalypse','disaster','재난','멸망','전쟁','war','end of the world']],
 ['미지와 우주','IDEA',['우주','space','alien','외계','미지','cosmic','planet','행성']],
 ['기술과 미래','IDEA',['기술','technology','future','미래','cyber','virtual','network','science fiction','sf']],
 ['꿈과 현실','VISUAL',['꿈','dream','reality','현실','환상','fantasy','surreal','초현실']],
 ['신체와 변형','VISUAL',['신체','body','body horror','변형','mutation','육체','괴물','monster']],
 ['도시적 고독','VISUAL',['도시','city','urban','metropolis','거리','아파트']],
 ['공간과 경계','VISUAL',['공간','space','집','house','room','방','경계','boundary','침입']],
 ['운명과 선택','STORY',['운명','fate','destiny','선택','choice','결정','시간','time']],
 ['정의와 죄책감','IDEA',['정의','justice','죄','guilt','복수','revenge','범죄','crime']],
 ['자연과 인간','IDEA',['자연','nature','환경','environment','생태','ecology','동물']],
 ['멜랑콜리','MOOD',['멜랑콜리','melancholy','슬픔','sad','우울','depression','쓸쓸']],
 ['불안과 공포','MOOD',['불안','anxiety','fear','공포','horror','두려','긴장']],
 ['유머와 아이러니','MOOD',['유머','humor','comedy','코미디','아이러니','satire','풍자']]
];
const FALLBACK={ANIME:['자아정체성','성장','연결의 실패','꿈과 현실','가족','불안과 공포'],FILM:['기억','사랑과 친밀감','공간과 경계','운명과 선택','상실','멜랑콜리'],TV:['가족','권력과 통제','성장','정의와 죄책감','사랑과 친밀감','연결의 실패'],BOOK:['존재와 죽음','기억','고독','성장','사랑과 친밀감','운명과 선택'],OTHER:['자아정체성','기억','연결의 실패','성장','고독','꿈과 현실']};
function stableHash(s){let h=2166136261;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function analyzeTaste(work,myComment,rating){const source=[work.title,work.original_title,work.creator,work.description,...(work.tags||[]),myComment].filter(Boolean).join(' ').toLowerCase();const found=[];for(const [tag,category,words] of LEXICON){let hits=0;for(const word of words)if(source.includes(word.toLowerCase()))hits++;if(hits)found.push({tag,category,score:Math.min(.96,.62+hits*.08+(myComment.toLowerCase().includes(tag.toLowerCase())?.06:0)),evidence:words.find(w=>source.includes(w.toLowerCase()))||tag})}const preferred=FALLBACK[work.media_type]||FALLBACK.OTHER;let cursor=stableHash(`${work.id}:${myComment}`)%preferred.length;while(found.length<6){const tag=preferred[cursor%preferred.length],entry=LEXICON.find(x=>x[0]===tag);if(entry&&!found.some(x=>x.tag===tag))found.push({tag,category:entry[1],score:.58+((stableHash(work.id+tag)%23)/100),evidence:(work.tags||[])[0]||work.media_type});cursor++}found.sort((a,b)=>b.score-a.score);const tags=found.slice(0,8).map((x,i)=>({...x,score:Number(Math.max(.5,x.score-i*.015).toFixed(2))}));const [a,b]=tags;const reflection=myComment?`“${myComment.slice(0,72)}${myComment.length>72?'…':''}”라는 감상에서 ${a.tag}과 ${b.tag}의 결을 읽었습니다.`:`${work.title}에서 ${a.tag}과 ${b.tag}의 결이 가장 선명하게 드러납니다.`;return{engine:'metadata-lexicon-v1',generatedAt:new Date().toISOString(),rating,tags,aiComment:reflection,summary:`${a.tag}을 중심으로 ${b.tag}과 맞닿는 작품`,cost:'free'}}
function sanitizeReview(p){return{rating:Math.max(1,Math.min(5,Number(p.rating)||5)),myComment:String(p.myComment||'').trim().slice(0,500)}}
async function archive(request,env){if(!dbReady(env))return json({error:'Supabase가 아직 연결되지 않았습니다.'},503);const user=currentUser(request);if(!user)return json({error:'로그인이 필요합니다.'},401);await ensureProfile(env,user);if(request.method==='GET'){const rows=await supabase(env,`archive_items?user_id=eq.${encodeURIComponent(user.id)}&select=created_at,rating,my_comment,ai_comment,analysis_status,analysis_json,works(*)&order=created_at.desc`);return json({items:(rows||[]).filter(x=>x.works).map(x=>toClientWork(x.works,x)),user:{email:user.email},engine:'metadata-lexicon-v1'})}if(request.method==='POST'){const p=await request.json(),work=normalizeWork(p.work||{});if(!work.id||!work.title)return json({error:'저장할 작품 정보가 올바르지 않습니다.'},400);const review=sanitizeReview(p),analysis=analyzeTaste(work,review.myComment,review.rating);await supabase(env,'works?on_conflict=id',{method:'POST',prefer:'resolution=merge-duplicates,return=minimal',body:work});const item={user_id:user.id,work_id:work.id,rating:review.rating,my_comment:review.myComment,ai_comment:analysis.aiComment,analysis_status:'complete',analysis_json:analysis};await supabase(env,'archive_items?on_conflict=user_id,work_id',{method:'POST',prefer:'resolution=merge-duplicates,return=minimal',body:item});await supabase(env,`taste_tags?user_id=eq.${encodeURIComponent(user.id)}&work_id=eq.${encodeURIComponent(work.id)}`,{method:'DELETE',prefer:'return=minimal'});await supabase(env,'taste_tags',{method:'POST',prefer:'return=minimal',body:analysis.tags.map(x=>({user_id:user.id,work_id:work.id,tag:x.tag,category:x.category,score:x.score,evidence:x.evidence,engine:analysis.engine}))});return json({saved:true,work:toClientWork(work,{...item,created_at:new Date().toISOString()})},201)}return json({error:'지원하지 않는 요청입니다.'},405)}
async function removeArchive(request,env,id){if(!dbReady(env))return json({error:'Supabase가 아직 연결되지 않았습니다.'},503);const user=currentUser(request);if(!user)return json({error:'로그인이 필요합니다.'},401);await supabase(env,`archive_items?user_id=eq.${encodeURIComponent(user.id)}&work_id=eq.${encodeURIComponent(id)}`,{method:'DELETE',prefer:'return=minimal'});return json({saved:false})}
async function tasteProfile(request,env){if(!dbReady(env))return json({error:'Supabase가 아직 연결되지 않았습니다.'},503);const user=currentUser(request);if(!user)return json({error:'로그인이 필요합니다.'},401);const rows=await supabase(env,`taste_tags?user_id=eq.${encodeURIComponent(user.id)}&select=tag,category,score,work_id`);const totals=new Map;for(const row of rows||[]){const p=totals.get(row.tag)||{tag:row.tag,category:row.category,total:0,count:0};p.total+=Number(row.score)||0;p.count++;totals.set(row.tag,p)}const tags=[...totals.values()].map(x=>({tag:x.tag,category:x.category,score:Math.round(Math.min(99,(x.total/x.count)*100+Math.min(8,x.count*2))),count:x.count})).sort((a,b)=>b.score-a.score).slice(0,8);const statement=tags.length>1?`당신은 장르보다 ‘${tags[0].tag}’과 ‘${tags[1].tag}’을 다루는 작품에 끌립니다.`:tags.length?`당신의 성좌에서 ‘${tags[0].tag}’의 빛이 가장 먼저 보입니다.`:'작품을 저장하면 당신만의 Taste DNA가 만들어집니다.';return json({tags,statement,engine:'metadata-lexicon-v1'})}
export default{async fetch(request,env){try{const u=new URL(request.url);if(u.pathname==='/api/search')return search(request,env);if(u.pathname==='/api/archive')return archive(request,env);if(u.pathname==='/api/taste-profile'&&request.method==='GET')return tasteProfile(request,env);if(u.pathname.startsWith('/api/archive/')&&request.method==='DELETE')return removeArchive(request,env,decodeURIComponent(u.pathname.slice(13)));if(u.pathname==='/api/health')return json({ok:true,sources:{tmdb:!!env.TMDB_READ_TOKEN,googleBooks:!!env.GOOGLE_BOOKS_API_KEY,openLibrary:true,aniList:true,supabase:dbReady(env),tasteEngine:'metadata-lexicon-v1'}});if(env.ASSETS)return env.ASSETS.fetch(request);return new Response('Not found',{status:404})}catch(error){console.error(error);return json({error:'요청을 처리하지 못했습니다. 잠시 후 다시 시도해 주세요.'},500)}}};
